     1	"use server";
     2	
     3	/**
     4	 * Posts a comment and fans out mention notifications; rate limited.
     5	 *
     6	 * Owner D. The notification fan-out itself is not triggered here — the service
     7	 * emits `comment.created` and `NotificationService` subscribes to it. This
     8	 * action only validates, authorizes, charges the rate limit and revalidates.
     9	 *
    10	 * Must call (do not reimplement): createCommentSchema, can, consumeRateLimit,
    11	 * getActor, toActionResult
    12	 */
    13	
    14	import { ForbiddenActionError, RateLimitedError } from "@/actions/_lib/action-errors";
    15	import { PENDING_COMMENT_ID } from "@/actions/_lib/permission-resources";
    16	import { withAction } from "@/actions/_lib/with-action";
    17	import { CACHE_PROFILES, issueTag, revalidateTagged } from "@/lib/cache";
    18	import { can } from "@/lib/permissions";
    19	import { consumeRateLimit } from "@/lib/rate-limit";
    20	import { createCommentSchema, type CreateCommentInput } from "@/schemas/comment";
    21	import { createComment } from "@/server/services/comment-service";
    22	import type { ActionResult } from "@/types/api";
    23	import type { Comment } from "@/types/comment";
    24	
    25	const COMMENT_BUCKET = "comment:create";
    26	
    27	const run = withAction<typeof createCommentSchema, Comment>(
    28	  createCommentSchema,
    29	  async (raw, actor) => {
    30	    const input = raw as CreateCommentInput;
    31	
    32	    const allowed = can(actor, "comment:create", {
    33	      kind: "comment",
    34	      orgId: input.orgId,
    35	      commentId: PENDING_COMMENT_ID,
    36	      authorId: actor.userId,
    37	    });
    38	    if (!allowed) {
    39	      throw new ForbiddenActionError("comment:create");
    40	    }
    41	
    42	    const verdict = await consumeRateLimit(input.orgId, COMMENT_BUCKET);
    43	    if (!verdict.allowed) {
    44	      throw new RateLimitedError(COMMENT_BUCKET, verdict.resetAt);
    45	    }
    46	
    47	    const comment = await createComment(actor, input);
    48	    revalidateTagged([issueTag(input.issueId)], CACHE_PROFILES.seconds);
    49	    return comment;
    50	  },
    51	  { revalidate: ["comments"], cacheProfile: "seconds" },
    52	);
    53	
    54	export async function createCommentAction(raw: unknown): Promise<ActionResult<Comment>> {
    55	  return run(raw);
    56	}
